#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *left;
    struct Node *right;
} Node;

Node *new_node(int value) {
    Node *p = (Node *)malloc(sizeof(Node));
    if (p == NULL) {
        return NULL;
    }
    p->value = value;
    p->left = NULL;
    p->right = NULL;
    return p;
}

Node *insert(Node *root, int value) {
    if (root == NULL) {
        return new_node(value);
    }
    if (value < root->value) {
        root->left = insert(root->left, value);
    } else if (value > root->value) {
        root->right = insert(root->right, value);
    }
    return root;
}

void preorder(Node *root) {
    if (root == NULL) {
        return;
    }
    printf("%d ", root->value);
    preorder(root->left);
    preorder(root->right);
}

void inorder(Node *root) {
    if (root == NULL) {
        return;
    }
    inorder(root->left);
    printf("%d ", root->value);
    inorder(root->right);
}

void postorder(Node *root) {
    if (root == NULL) {
        return;
    }
    postorder(root->left);
    postorder(root->right);
    printf("%d ", root->value);
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 1;
    }
    Node *root = NULL;
    for (int i = 0; i < n; i++) {
        int v;
        if (scanf("%d", &v) != 1) {
            return 1;
        }
        root = insert(root, v);
    }

    printf("前序：");
    preorder(root);
    printf("\n中序：");
    inorder(root);
    printf("\n后序：");
    postorder(root);
    printf("\n");
    return 0;
}
